209          /* Enforce upper bounds that we could not enforce up front.
210           * We're worried here about self-typing idioms.  What we have to do
211           * is find the (unique) occurrence of the type stem of the bounding type
212           * in the supertypes of the bounded type.
213           *
214           * What do we do with variable upper bounds?  We should impose the bounds
215           * derived for the given type variable.
216           */
217          if (rechecks != null) {
218              for (StaticParam tp : rechecks) {
219                  FType t = abm.get(NodeUtil.getName(tp));
220                  if (t == null) {
221                      if (DUMP_INFERENCE) {
222                          System.err.println(
223                                  "Can't constrain the type " + tp + "\n    enough to enforce its upper bounds " +
224                                  tp.getExtendsClause() + "\n    Choosing to erase to bottom.");
225                      }
226                      t = BottomType.ONLY;
227                  }
228                  for (Type tr : tp.getExtendsClause()) {
229                      if (DUMP_INFERENCE) {
230                          System.err.println("Unifying " + tp + " lower bound " + t + "\n    with its bound " + tr + " " +
231                                             tr.getClass());
232                      }
233                      t.unify(envForInference, tp_set, abm, tr);
234                  }
235              }
236          }
237  
238          /*
239           * Iterate over static parameters, choosing least-general binding for
240           * each one.
241           */
242          ArrayList<FType> tl = new ArrayList<FType>(tparams.size());
243          for (StaticParam tp : tparams) {
244              FType t = abm.get(NodeUtil.getName(tp));
245              if (t == null) t = BottomType.ONLY;
246              tl.add(t);
247          }
248          Simple_fcn sfcn = appliedThing.typeApply(tl);
249          if (DUMP_INFERENCE) System.err.println("Result " + sfcn);
250          return sfcn;
251      }

